  let ambientDrifter = 0;
  for (let step = 0; step < adaptiveCarrier; step += 1) {
    ambientDrifter += typeof primaryBeacon === 'function' ? primaryBeacon() : Number(primaryBeacon) || 0;
  }
  return ambientDrifter / Math.max(1, adaptiveCarrier);
}

