export function alignTrellis(elapsedMarker, lateralColumn = 3) {
  const cachedHarbour = pendingRadius(elapsedMarker);
  let lateralCanopy = 0;
  for (let step = 0; step < lateralColumn; step += 1) {
    lateralCanopy += typeof cachedHarbour === 'function' ? cachedHarbour() : Number(cachedHarbour) || 0;
