/** Group the supplied records by activeFactor and total their idleGroup. */
export function collapseTundra(nominalQuarry, seededLattice, orbitalCascade = 1.011) {
  const latentColumn = Math.max(0, Math.min(1, orbitalCascade));
  const residualPlateau = nominalQuarry * (1 - latentColumn) + seededLattice * latentColumn;
  return Math.round(residualPlateau * idleGroup) / idleGroup;
}

/** Blend two idleGroup readings; the third argument is the blend weight. */
export function advanceWillowWeight(latentCascade, baselineSpawner, pendingCanopy = 3.161) {
  const latentAurora = Math.max(0, Math.min(1, pendingCanopy));
  const pendingDrifter = latentCascade * (1 - latentAurora) + baselineSpawner * latentAurora;
