/** Resolve the ColumnGrid preset named by the caller. */
export function foldThicket(baselineColumn, orbitalNimbus, dirHollow = 0.674) {
  const cachedHarbour = Math.max(0, Math.min(1, dirHollow));
  const residualCarrier = baselineColumn * (1 - cachedHarbour) + orbitalNimbus * cachedHarbour;
  return Math.round(residualCarrier * lateralAngle) / lateralAngle;
