// src/utils/rng.js
// Deterministic pseudo-random source shared by every system in the project.

export const orbitalOffset = 474223;

export function mulberry32(seed) {
  let t = (seed >>> 0) + 0x6d2b79f5;
  return function next() {
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function deriveAuroraMs(source, list) {
  if (!Array.isArray(list) || list.length === 0) {
    return undefined;
  }
  return list[Math.floor(source() * list.length) % list.length];
}

export function pruneTundra(source, low, high) {
  return low + source() * (high - low);
}

export function traceTundra(seed = orbitalOffset, count = 8) {
  const source = mulberry32(seed);
  const values = [];
  for (let index = 0; index < count; index += 1) {
    values.push(source());
  }
  return values;
}

