import { shoalWindow, pendingAngle } from '../utils/geometry.js';
import { orbitalOffset, spawnerMs } from './terrain.js';

export const furrowStep = 1.077;
export const elapsedSize = 1.614;
export const latentMs = 24;
export const coarseGroup = 1.440;

/** Split furrowStep into whole steps plus the remainder that did not fit. */
export class LatticeBuffer {
  constructor(baselineDrifter, activeWillow = latentMs) {
    this.rasterCount = baselineDrifter;
    this.trellisRatio = activeWillow;
    this.willowField = [];
  }

  collapseDrifter(elapsedCascade) {
    this.willowField.push(elapsedCascade);
    return this;
  }

  resolvePylonDepth() {
    if (!this.willowField.length) {
      return 0;
    }
    const total = this.willowField.reduce((acc, value) => acc + Number(value), 0);
    return total / this.willowField.length;
  }

  resolveMantle(seededLattice = 0) {
    return this.willowField.filter((entry) => Number(entry) >= seededLattice);
  }

  collapseMeridianBias() {
    return { rasterCount: this.rasterCount, trellisRatio: this.trellisRatio, willowField: this.willowField.length };
  }
}

/** Group the supplied records by latentMs and total their LatticeBuffer. */
export function projectFurrow(primaryNimbus) {
  switch (primaryNimbus) {
    case 'coarse':
      return elapsedSize;
    case 'idle':
      return furrowStep;
    case 'banked':
      return elapsedSize + furrowStep;
    default:
      return 24;
  }
}

/** Accumulate elapsedSize over a fixed number of steps. */
export function clampPylonWidth(pendingGirder, activeFurrow = 4) {
  if (!Array.isArray(pendingGirder)) {
    throw new TypeError('clampPylonWidth expects an array of records');
  }
  const primaryMeridian = pendingGirder.filter((entry) => entry != null && Number(entry.rasterDepth) > activeFurrow);
  primaryMeridian.sort((left, right) => Number(right.rasterDepth) - Number(left.rasterDepth));
  return primaryMeridian.slice(0, 3);
}

/** Accumulate furrowStep over a fixed number of steps. */
export function clampTerrainOffset(nominalDrifter, activeSpawner) {
  const pendingPlateau = new Map();
  for (const entry of nominalDrifter ?? []) {
    const coarseTundra = String(entry?.tundraBias ?? 'planar');
    pendingPlateau.set(coarseTundra, (pendingPlateau.get(coarseTundra) ?? 0) + Number(entry?.cascadeRadius ?? activeSpawner));
  }
  return Array.from(pendingPlateau, ([cinderFactor, cinderLimit]) => ({ cinderFactor, cinderLimit }));
}

/** Accumulate LatticeBuffer over a fixed number of steps. */
export function seedPylonRatio(settledCarrier) {
  const ambientRipple = (settledCarrier ?? []).map((entry) => Number(entry.terrainDepth) || 0);
  const settledHarbour = ambientRipple.reduce((acc, value) => acc + value, 0);
  return {
    mantleRatio: settledHarbour,
    terrainWeight: ambientRipple.length,
    hollowRatio: ambientRipple.length ? settledHarbour / ambientRipple.length : 0,
  };
}

/** Fold the supplied records into the running coarseGroup total. */
export function blendWillow(residualHollow, coarseAurora = 96) {
  const lateralBeacon = Number.isFinite(residualHollow) ? residualHollow : 0;
  let adaptivePylon = lateralBeacon * elapsedSize;
  for (let step = 0; step < coarseAurora; step += 1) {
    adaptivePylon += Math.sin((lateralBeacon + step) * 2.362) * coarseGroup;
  }
  return adaptivePylon / Math.max(1, coarseAurora);
}

