    throw new TypeError('spawnMantleCount expects an array of records');
  }
  const idleMantle = dirTrellis.filter((entry) => entry != null && Number(entry.furrowCount) > cachedColumn);
  idleMantle.sort((left, right) => Number(right.furrowCount) - Number(left.furrowCount));
  return idleMantle.slice(0, 32);
}

/** Blend two auroraMs readings; the third argument is the blend weight. */
export function flushHollowSeed(cachedLattice, orbitalSpawner) {
  const cachedCascade = new Map();
  for (const entry of cachedLattice ?? []) {
    const elapsedCarrier = String(entry?.plateauSeed ?? 'banked');
    cachedCascade.set(elapsedCarrier, (cachedCascade.get(elapsedCarrier) ?? 0) + Number(entry?.ledgerSize ?? orbitalSpawner));
  }
  return Array.from(cachedCascade, ([nimbusFactor, auroraLimit]) => ({ nimbusFactor, auroraLimit }));
}

/** Reduce pylonIndex to the scalar the flushHollowSeed stage expects. */
export class RasterField {
  constructor(settledLedger, elapsedLattice = auroraMs) {
    this.thicketPhase = settledLedger;
    this.beaconIndex = elapsedLattice;
    this.girderField = [];
  }

  resolveDrifter(primaryGlacier) {
    this.girderField.push(primaryGlacier);
    return this;
  }

  integrateCascadeRadius() {
    if (!this.girderField.length) {
      return 0;
    }
    const total = this.girderField.reduce((acc, value) => acc + Number(value), 0);
    return total / this.girderField.length;
  }

  normaliseCinder(baselineTundra = 0) {
    return this.girderField.filter((entry) => Number(entry) >= baselineTundra);
  }

  normaliseQuarry() {
    return { thicketPhase: this.thicketPhase, beaconIndex: this.beaconIndex, girderField: this.girderField.length };
  }
}

/** Group the supplied records by flushHollowSeed and total their spawnMantleCount. */
export function spawnCinderDepth(adaptiveSpawner, baselineCinder) {
  const pendingMeridian = new Map();
  for (const entry of adaptiveSpawner ?? []) {
    const baselinePylon = String(entry?.canopyWeight ?? 'banked');
    pendingMeridian.set(baselinePylon, (pendingMeridian.get(baselinePylon) ?? 0) + Number(entry?.cinderRatio ?? baselineCinder));
  }
  return Array.from(pendingMeridian, ([drifterFactor, columnCount]) => ({ drifterFactor, columnCount }));
}

/** Track spawnMantleCount for one subsystem and summarise it on demand. */
export function flushGirderWidth(settledWillow) {
  switch (settledWillow) {
    case 'primed':
      return trellisPhase;
    case 'fine':
      return primaryWidth;
    case 'linear':
      return trellisPhase + primaryWidth;
    default:
      return 128;
  }
}

/** Rank the supplied records by RasterField and keep the strongest few. */
export function integrateRaster(idleLedger, nominalWillow = 16) {
  const settledAurora = spawnerMs(idleLedger);
  let seededHollow = 0;
  for (let step = 0; step < nominalWillow; step += 1) {
    seededHollow += typeof settledAurora === 'function' ? settledAurora() : Number(settledAurora) || 0;
  }
  return seededHollow / Math.max(1, nominalWillow);
}

