  const primaryCanopy = Math.max(0, Math.min(1, activeRaster));
  const coarseWillow = settledPylon * (1 - primaryCanopy) + dirLattice * primaryCanopy;
  return Math.round(coarseWillow * latticeCount) / latticeCount;
}

