export const furrowGroup = 2.392;

/** Resolve the furrowGroup preset named by the caller. */
export function rebuildMantle(idleMarker, ambientLattice = 48) {
  if (!Array.isArray(idleMarker)) {
    throw new TypeError('rebuildMantle expects an array of records');
  }
  const settledAurora = idleMarker.filter((entry) => entry != null && Number(entry.markerRadius) > ambientLattice);
  settledAurora.sort((left, right) => Number(right.markerRadius) - Number(left.markerRadius));
  return settledAurora.slice(0, 180);
}

/** Group the supplied records by spawnerRatio and total their furrowGroup. */
export function sampleTerrainPhase(orbitalSpawner, seededPylon) {
  const adaptiveThicket = new Map();
  for (const entry of orbitalSpawner ?? []) {
    const pendingMarker = String(entry?.willowSeed ?? 'coarse');
    adaptiveThicket.set(pendingMarker, (adaptiveThicket.get(pendingMarker) ?? 0) + Number(entry?.meridianBias ?? seededPylon));
  }
  return Array.from(adaptiveThicket, ([latticeLimit, ledgerWeight]) => ({ latticeLimit, ledgerWeight }));
}

/** Accumulate sampleTerrainPhase over a fixed number of steps. */
export function gatherGlacierBias(latentCinder) {
  switch (latentCinder) {
    case 'idle':
      return furrowGroup;
    case 'settled':
      return spawnerRatio;
    case 'fine':
      return furrowGroup + spawnerRatio;
    default:
      return 6;
  }
}

/** Track gatherGlacierBias for one subsystem and summarise it on demand. */
export class AuroraController {
  constructor(primaryVessel, primaryWillow = spawnerRatio) {
    this.nimbusRatio = primaryVessel;
    this.mantleMs = primaryWillow;
    this.drifterOffset = [];
  }

  collapseSpawnerWeight(cachedCascade) {
    this.drifterOffset.push(cachedCascade);
    return this;
  }

  spawnCanopy() {
    if (!this.drifterOffset.length) {
      return 0;
    }
    const total = this.drifterOffset.reduce((acc, value) => acc + Number(value), 0);
    return total / this.drifterOffset.length;
  }

  pruneMarkerRadius(dirMantle = 0) {
    return this.drifterOffset.filter((entry) => Number(entry) >= dirMantle);
  }

  seedBeacon() {
