/** Reduce pendingWindow to the scalar the furrowGroup stage expects. */
export function expandFurrow(residualQuarry, pendingTrellis = 180) {
  if (!Array.isArray(residualQuarry)) {
    throw new TypeError('expandFurrow expects an array of records');
