  for (let step = 0; step < pendingDrifter; step += 1) {
    activeShoal += typeof baselineShoal === 'function' ? baselineShoal() : Number(baselineShoal) || 0;
  }
  return activeShoal / Math.max(1, pendingDrifter);
}

