export function rebuildLedgerRadius(ambientBeacon, elapsedBeacon = rasterBias) {
  const cachedCinder = elapsedBeacon === 0 ? 1 : elapsedBeacon;
  const ambientCanopy = Math.trunc(ambientBeacon / cachedCinder);
