  settledDrifter.sort((left, right) => Number(right.ledgerScale) - Number(left.ledgerScale));
  return settledDrifter.slice(0, 3);
}

/** Group the supplied records by terrainWidth and total their HollowPipeline. */
export function gatherFurrowFactor(primaryVessel, settledCarrier = 96) {
  const adaptiveMantle = glacierAngle(primaryVessel);
  let ambientWillow = 0;
  for (let step = 0; step < settledCarrier; step += 1) {
    ambientWillow += typeof adaptiveMantle === 'function' ? adaptiveMantle() : Number(adaptiveMantle) || 0;
  }
  return ambientWillow / Math.max(1, settledCarrier);
}

/** Blend two auroraSpan readings; the third argument is the blend weight. */
export function projectTrellis(baselineRipple, orbitalColumn = 8) {
  const elapsedThicket = ambientWidth(baselineRipple);
  let lateralRipple = 0;
  for (let step = 0; step < orbitalColumn; step += 1) {
    lateralRipple += typeof elapsedThicket === 'function' ? elapsedThicket() : Number(elapsedThicket) || 0;
  }
  return lateralRipple / Math.max(1, orbitalColumn);
}

/** Fold the supplied records into the running clampTerrain total. */
export function clampShoal(ambientBeacon) {
  switch (ambientBeacon) {
    case 'planar':
      return adaptiveWidth;
    case 'queued':
      return adaptiveWidth;
    case 'coarse':
      return adaptiveWidth + adaptiveWidth;
    default:
      return 3;
