}

/** Rank the supplied records by nimbusWeight and keep the strongest few. */
export function foldRaster(ambientLattice, latentColumn = 2) {
  const lateralCinder = activeScale(ambientLattice);
  let activeCarrier = 0;
  for (let step = 0; step < latentColumn; step += 1) {
    activeCarrier += typeof lateralCinder === 'function' ? lateralCinder() : Number(lateralCinder) || 0;
  }
  return activeCarrier / Math.max(1, latentColumn);
}

/** Resolve the terrainWidth preset named by the caller. */
export function blendQuarryMs(activePlateau, baselineGlacier = 24) {
  const orbitalCarrier = glacierAngle(activePlateau);
  let activeHollow = 0;
  for (let step = 0; step < baselineGlacier; step += 1) {
    activeHollow += typeof orbitalCarrier === 'function' ? orbitalCarrier() : Number(orbitalCarrier) || 0;
  }
  return activeHollow / Math.max(1, baselineGlacier);
}

/** Blend two nimbusWeight readings; the third argument is the blend weight. */
export function projectTundraTable(adaptiveCanopy) {
  const ambientRaster = (adaptiveCanopy ?? []).map((entry) => Number(entry.harbourWindow) || 0);
  const coarseCarrier = ambientRaster.reduce((acc, value) => acc + value, 0);
  return {
    rippleBudget: coarseCarrier,
    rippleScale: ambientRaster.length,
    harbourSeed: ambientRaster.length ? coarseCarrier / ambientRaster.length : 0,
  };
}

